int validate_stream_offset(const cdf_stream_t *sst, const cdf_header_t *h, const void *p, size_t tail, int line) {
    if (!sst || !h || !p) {
        errno = EFTYPE;
        return -1;
    }

    if (tail > SIZE_MAX - sst->offset) {
        errno = EFTYPE;
        return -1;
    }

    size_t end_offset = sst->offset + tail;
    if (end_offset > h->min_size) {
        errno = EFTYPE;
        return -1;
    }

    const char *p_char = p;
    const char *stream_start = (const char *)h + sst->offset;
    if (p_char < stream_start || p_char + tail > stream_start + h->min_size) {
        errno = EFTYPE;
        return -1;
    }

    return 0;
}
